<?php require_once "../db.php";require_role("Teacher");$uid=current_id();$qid=(int)($_GET['quiz_id']??0);$date=$_GET['date']??'';$st=$conn->prepare("SELECT s.name student_name,s.semester,h.score,h.total_questions,h.attempted_questions,h.created_at,q.title,q.subject FROM quiz_history h JOIN student s ON s.id=h.student_id JOIN quiz q ON q.id=h.quiz_id WHERE q.id=? AND q.created_by=? AND DATE(h.created_at)=? ORDER BY s.name");$st->bind_param("iis",$qid,$uid,$date);$st->execute();$r=$st->get_result();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Students by Quiz Date</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-4"><a href="results.php" class="btn btn-outline-primary mb-3">← Quiz History</a><h2><?=e($date)?> — Student Attempts</h2><div class="card panel-card"><div class="card-body table-responsive"><table class="table table-striped"><thead><tr><th>Student</th><th>Semester</th><th>Subject</th><th>Quiz</th><th>Score</th><th>Attempted</th><th>Submitted at</th></tr></thead><tbody><?php while($d=$r->fetch_assoc()):?><tr><td><?=e($d['student_name'])?></td><td><?=e($d['semester'])?></td><td><?=e($d['subject'])?></td><td><?=e($d['title'])?></td><td><?=$d['score']?>/<?=$d['total_questions']?></td><td><?=$d['attempted_questions']?></td><td><?=e($d['created_at'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>